// Generated by scripts/landing-port/build.py. Do not edit by hand.
export default function init() {
var __root = document.querySelector('.lpx'); if (__root) __root.classList.add('js');

(function () {
  'use strict';

  /* ============ GO-LIVE SETTINGS: fill these in, nothing else needs editing ============ */
  var CONFIG = {
    HUBSPOT_PORTAL_ID: 'YOUR_HUBSPOT_PORTAL_ID',  // HubSpot > Settings > Account (Hub ID)
    HUBSPOT_FORM_GUID: 'YOUR_HUBSPOT_FORM_GUID',  // HubSpot > Marketing > Forms > your form
    GOOGLE_ADS_ID: 'AW-18402352411',               // Google Ads > Tools > Conversions > Tag setup
    GOOGLE_ADS_LABEL: 'CczACNCuneUcEJu69sZE'      // conversion label for the lead form
  };
  // The HubSpot form needs these fields: firstname, email, phone, company, message
  /* ====================================================================================== */

  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  function isSet(v) { return v && v.indexOf('YOUR_') !== 0 && v.indexOf('XXXX') === -1; }
  function $(id) { return document.getElementById(id); }

  /* ---- Google tag: loads only once a real ID is entered ---- */
  if (isSet(CONFIG.GOOGLE_ADS_ID)) {
    var gs = document.createElement('script');
    gs.async = true;
    gs.src = 'https://www.googletagmanager.com/gtag/js?id=' + CONFIG.GOOGLE_ADS_ID;
    document.head.appendChild(gs);
    window.dataLayer = window.dataLayer || [];
    window.gtag = function () { window.dataLayer.push(arguments); };
    window.gtag('js', new Date());
    window.gtag('config', CONFIG.GOOGLE_ADS_ID);
  }

  /* ---- Count-up numbers ---- */
  function countUp(el) {
    var end = parseFloat(el.getAttribute('data-count'));
    var suf = el.getAttribute('data-suffix') || '';
    if (reduce) { el.textContent = end + suf; return; }
    var t0 = null, dur = 1500;
    function frame(t) {
      if (!t0) t0 = t;
      var p = Math.min((t - t0) / dur, 1);
      el.textContent = Math.round(end * (1 - Math.pow(1 - p, 3))) + suf;
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  /* ---- Hero scene: gentle parallax that follows the pointer ---- */
  var scene = $('heroScene'), hero = document.querySelector('.hero');
  if (scene && !reduce && window.matchMedia('(hover: hover)').matches) {
    hero.addEventListener('mousemove', function (e) {
      var r = hero.getBoundingClientRect();
      scene.style.setProperty('--mx', ((e.clientX - r.left) / r.width - 0.5).toFixed(3));
      scene.style.setProperty('--my', ((e.clientY - r.top) / r.height - 0.5).toFixed(3));
    });
  }

  /* ---- Interactive showcase: three steps the visitor can switch between ---- */
  var tabs = [$('tab0'), $('tab1'), $('tab2')];
  var screens = document.querySelectorAll('.screen');
  var typedEl = $('typed'), adRow = $('adRow'), chipS = $('chipS'), chipT = $('chipT'), chipR = $('chipR'), rep = $('rep');
  var nodes = document.querySelectorAll('.node'), wires = document.querySelectorAll('.wire');
  var QUERY = 'custom website development';
  var current = 0, token = 0, timers = [], userPicked = false, inView = false;

  function later(my, fn, ms) { timers.push(setTimeout(function () { if (my === token) fn(); }, ms)); }
  function clearAll() { token++; timers.forEach(clearTimeout); timers = []; }
  function showScreen(i) {
    current = i;
    screens.forEach(function (s) { s.classList.toggle('on', +s.getAttribute('data-s') === i); });
    tabs.forEach(function (t, k) { t.setAttribute('aria-selected', k === i ? 'true' : 'false'); });
  }
  function resetScenes() {
    typedEl.textContent = ''; adRow.classList.remove('in'); chipS.classList.remove('on');
    nodes.forEach(function (n) { n.classList.remove('on'); }); wires.forEach(function (w) { w.classList.remove('on'); });
    chipT.classList.remove('on'); rep.classList.remove('on'); chipR.classList.remove('on');
  }
  function renderFinal(i) {
    resetScenes();
    if (i === 0) { typedEl.textContent = QUERY; adRow.classList.add('in'); chipS.classList.add('on'); }
    if (i === 1) { nodes.forEach(function (n) { n.classList.add('on'); }); wires.forEach(function (w) { w.classList.add('on'); }); chipT.classList.add('on'); }
    if (i === 2) { rep.classList.add('on'); chipR.classList.add('on'); }
  }
  function playSearch(my, done) {
    var k = 0;
    (function typeNext() {
      if (k >= QUERY.length) {
        later(my, function () { adRow.classList.add('in'); }, 300);
        later(my, function () { chipS.classList.add('on'); }, 1300);
        return later(my, done, 2800);
      }
      typedEl.textContent = QUERY.slice(0, ++k);
      later(my, typeNext, 60);
    })();
  }
  function playTrack(my, done) {
    later(my, function () { nodes[0].classList.add('on'); }, 400);
    later(my, function () { wires[0].classList.add('on'); }, 900);
    later(my, function () { nodes[1].classList.add('on'); }, 1700);
    later(my, function () { wires[1].classList.add('on'); }, 2200);
    later(my, function () { nodes[2].classList.add('on'); }, 3000);
    later(my, function () { chipT.classList.add('on'); }, 3600);
    later(my, done, 5000);
  }
  function playRep(my, done) {
    later(my, function () { rep.classList.add('on'); }, 300);
    later(my, function () { chipR.classList.add('on'); }, 2200);
    later(my, done, 3800);
  }
  function play(i) {
    clearAll(); var my = token; showScreen(i); resetScenes();
    if (reduce) { renderFinal(i); return; }
    function done() { later(my, function () { play(userPicked ? i : (i + 1) % 3); }, userPicked ? 3500 : 1600); }
    if (i === 0) playSearch(my, done); else if (i === 1) playTrack(my, done); else playRep(my, done);
  }
  tabs.forEach(function (t, k) {
    t.addEventListener('click', function () { userPicked = true; play(+t.getAttribute('data-i')); });
    t.addEventListener('keydown', function (e) {
      if (e.key !== 'ArrowDown' && e.key !== 'ArrowRight' && e.key !== 'ArrowUp' && e.key !== 'ArrowLeft') return;
      e.preventDefault();
      var n = (k + (e.key === 'ArrowDown' || e.key === 'ArrowRight' ? 1 : 2)) % 3;
      tabs[n].focus(); userPicked = true; play(n);
    });
  });

  /* ---- Scroll reveal, counters, budget donut, and starting the showcase when it is on screen ---- */
  var targets = document.querySelectorAll('.reveal, [data-count], #stage, .cmp');
  document.querySelectorAll('[data-count]').forEach(function (el) {
    if ('IntersectionObserver' in window && !reduce) el.textContent = '0' + (el.getAttribute('data-suffix') || '');
  });
  if ('IntersectionObserver' in window) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) {
        var el = e.target;
        if (el.id === 'stage') {
          if (e.isIntersecting && !inView) { inView = true; play(current); }
          else if (!e.isIntersecting && inView) { inView = false; clearAll(); }
          return;
        }
        if (!e.isIntersecting) return;
        el.classList.add('is-visible');
        if (el.hasAttribute('data-count')) countUp(el);
        io.unobserve(el);
      });
    }, { threshold: 0.08, rootMargin: '0px 0px -6% 0px' });
    targets.forEach(function (el) { io.observe(el); });
  } else {
    targets.forEach(function (el) { el.classList.add('is-visible'); if (el.hasAttribute('data-count')) countUp(el); });
    play(0);
  }

  /* ---- Mobile call bar: shown after the hero, hidden while the form is on screen ---- */
  var mbar = $('mbar'), formCard = $('enquire'), formVisible = true, scrolled = false;
  function syncBar() { mbar.classList.toggle('show', scrolled && !formVisible); }
  window.addEventListener('scroll', function () { scrolled = window.scrollY > 400; syncBar(); }, { passive: true });
  if ('IntersectionObserver' in window) {
    new IntersectionObserver(function (es) { formVisible = es[0].isIntersecting; syncBar(); }, { threshold: 0.1 }).observe(formCard);
  }

  /* ---- Attribution from the ad click ---- */
  var qs = new URLSearchParams(window.location.search);
  var attribution = ['gclid', 'utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content']
    .map(function (k) { return qs.get(k) ? k + ': ' + qs.get(k) : null; }).filter(Boolean).join(' | ');

  /* ---- Qualifying form: two quick questions, then the details ---- */
  var form = $('leadCaptureForm');
  var panes = { s1: $('step1'), s2: $('step2'), ok: $('success') };
  function show(which) {
    Object.keys(panes).forEach(function (k) { panes[k].hidden = (k !== which); });
    $('p2').classList.toggle('on', which === 's2');
    $('stepLbl').textContent = which === 's2' ? 'Step 2 of 2' : 'Step 1 of 2';
    var bare = (which === 'ok');
    $('stepLbl').hidden = bare;
    document.querySelector('.prog').hidden = bare;
  }
  function val(name) { var c = form.querySelector('input[name="' + name + '"]:checked'); return c ? c.value : ''; }
  $('toStep2').addEventListener('click', function () {
    var err = $('pickErr');
    if (!val('role') || !val('budget')) { err.classList.add('show'); return; }
    err.classList.remove('show');
    show('s2');
    $('f-name').focus({ preventScroll: true });
  });
  $('backTo1').addEventListener('click', function () { show('s1'); });

  function validPhone(v) {
    var d = v.replace(/[\s\-()+]/g, '');
    if (d.length === 12 && d.indexOf('91') === 0) d = d.slice(2);
    if (d.length === 11 && d[0] === '0') d = d.slice(1);
    return /^[6-9]\d{9}$/.test(d) && !/^(\d)\1{9}$/.test(d) && ['9876543210','1234567890','9123456789'].indexOf(d) === -1;
  }
  var rules = {
    'f-name': function (v) { return v.trim().length >= 2; },
    'f-email': function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()); },
    'f-phone': validPhone,
    'f-company': function (v) { return v.trim().length >= 2; },
    'f-goal': function () { return true; }
  };
  function check(id) {
    var el = $(id), ok = rules[id](el.value);
    el.closest('.fld').classList.toggle('bad', !ok);
    return ok;
  }
  Object.keys(rules).forEach(function (id) {
    $(id).addEventListener('blur', function () { check(id); });
    $(id).addEventListener('input', function () { if ($(id).closest('.fld').classList.contains('bad')) check(id); });
  });
  var ROLES = { owner: 'Founder or business owner', head: 'Marketing, product or business head', ops: 'Operations, IT or finance head', leader: 'Director, VP or other senior leader' };
  var BUDGETS = { 'not-running': 'Not running paid ads yet', 'under-1l': 'Under Rs 1 lakh / month', '1l-5l': 'Rs 1L to Rs 5L / month', '5l-plus': 'Rs 5 lakh+ / month' };
  var statusEl = $('status'), submitBtn = $('submitBtn');
  function showSuccess() { show('ok'); $('success').focus(); }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var allOk = true, firstBad = null;
    Object.keys(rules).forEach(function (id) { if (!check(id)) { allOk = false; if (!firstBad) firstBad = id; } });
    if (!allOk) { $(firstBad).focus(); return; }
    if (form.elements.hp_field.value) { showSuccess(); return; }   // bots fill the hidden field

    
    var message = ['Role: ' + (ROLES[val('role')] || val('role')), 'Monthly ad budget: ' + (BUDGETS[val('budget')] || val('budget')),
                   (form.elements.goal.value.trim() ? 'Goal: ' + form.elements.goal.value.trim() : '')]
      .filter(Boolean).join(' | ');

    submitBtn.disabled = true;
    statusEl.textContent = 'Sending...';
    fetch('/api/leads', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: form.elements.name.value.trim(),
        email: form.elements.email.value.trim(),
        phone: form.elements.phone.value.trim(),
        company: form.elements.company.value.trim(),
        website: form.elements.website ? form.elements.website.value.trim() : undefined,
        pillar: 'Digital Marketing',
        message: message,
        source_page: '/google-ads-agency-pune',
        _gotcha: form.elements.hp_field ? form.elements.hp_field.value : ''
      })
    })
    .then(function (r) { if (r.status === 400) { var e = new Error('bad'); e.bad = true; throw e; } if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
    .then(function () {
      window.dataLayer = window.dataLayer || []; window.dataLayer.push({ event: 'lead_form_submit', form_name: 'lp-google-ads-pune' });
      showSuccess();
      if (window.gtag && isSet(CONFIG.GOOGLE_ADS_ID) && isSet(CONFIG.GOOGLE_ADS_LABEL)) {
        window.gtag('event', 'conversion', { send_to: CONFIG.GOOGLE_ADS_ID + '/' + CONFIG.GOOGLE_ADS_LABEL });
      }
    })
    .catch(function (err) { statusEl.textContent = (err && err.bad) ? 'Please check your name, email and 10-digit phone number, then try again.' : 'Something went wrong. Please call us on +91 97645 66644.'; })
    .finally(function () { submitBtn.disabled = false; });
  });
})();

}
